#!/usr/bin/env python3
"""OneSite Studio: independent, local project editor and CLI supervisor.

Run with the Python environment in which OneSite is installed::

    python webui.py [--port 8765] [--projects-dir ./projects] [--no-browser]

Only the Python standard library is needed by this file. OneSite is accessed
in child processes, never imported into the HTTP server. Project Python is
parsed, not executed, when opening, previewing, or saving an editor document.
"""

from __future__ import annotations

import argparse
import ast
import base64
import copy
import hashlib
import json
import keyword
import os
from pathlib import Path, PurePosixPath
import pprint
import re
import secrets
import shutil
import signal
import subprocess
import sys
import tempfile
import textwrap
import threading
import time
from collections import deque
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit
import webbrowser


MAX_BODY = 16 * 1024 * 1024
MAX_FILE = 2 * 1024 * 1024
TEXT_EXTENSIONS = {
    ".py",
    ".json",
    ".yaml",
    ".yml",
    ".toml",
    ".txt",
    ".md",
    ".ts",
    ".tsx",
    ".js",
    ".jsx",
    ".css",
    ".html",
    ".svg",
    ".sql",
    ".sh",
    ".rs",
    ".go",
    ".mod",
    ".sum",
    ".lock",
    ".ini",
    ".mako",
}
SKIP_DIRS = {"__pycache__", "node_modules", ".git", ".venv", "target", "dist"}
MODEL_IMPORTS = """from typing import Any, Optional, List, Dict
from datetime import date, datetime, timezone
from decimal import Decimal
from enum import Enum
from uuid import UUID, uuid4
from sqlalchemy import Column, JSON, DateTime
from sqlmodel import Field, Relationship, SQLModel
"""
HOOKS = {
    "on_before_create": ("self, session, context", "创建前；可修改 self，抛出异常会回滚事务。"),
    "on_after_create": ("self, session, context", "创建后、事务提交前；可使用同一 session。"),
    "on_before_update": (
        "self, session, old, changes, context",
        "更新前；old 为旧值，changes 为更新内容。",
    ),
    "on_after_update": ("self, session, old, changes, context", "更新后、事务提交前。"),
    "on_before_delete": ("self, session, old, context", "删除前、事务内。"),
    "on_after_delete": ("self, session, old, context", "删除后、事务提交前。"),
    "on_after_commit_create": (
        "self, context",
        "创建提交后；适合通知等外部副作用，不提供 session。",
    ),
    "on_after_commit_update": ("self, old, changes, context", "更新提交后；适合通知等外部副作用。"),
    "on_after_commit_delete": ("self, old, context", "删除提交后。"),
    "on_after_bulk_delete": (
        "cls, session, olds, context",
        "批量删除后、事务内；必须是 classmethod。",
    ),
    "on_after_commit_bulk_delete": ("cls, olds, context", "批量删除提交后；必须是 classmethod。"),
}


class EditorError(Exception):
    def __init__(self, message: str, status: int = 400):
        super().__init__(message)
        self.status = status


def python_literal(value):
    return pprint.pformat(value, width=100, sort_dicts=False)


def check_python(source: str, filename: str):
    try:
        tree = ast.parse(source, filename=filename)
        compile(tree, filename, "exec")
        return tree
    except (SyntaxError, ValueError) as exc:
        raise EditorError(f"{filename}: {exc}") from exc


def identifier(value: str):
    if not isinstance(value, str) or not value.isidentifier() or keyword.iskeyword(value):
        raise EditorError(f"无效的 Python 标识符：{value!r}")
    return value


def expression(value: str):
    if not isinstance(value, str) or not value.strip():
        raise EditorError("Python 表达式不能为空")
    try:
        ast.parse(value, mode="eval")
    except SyntaxError as exc:
        raise EditorError(f"无效的 Python 表达式：{value}: {exc.msg}") from exc
    return value


def static_value(node):
    """Read literal config and typed config constructors without executing them."""
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
        if node.func.id == "sqlite_url" and not node.keywords and len(node.args) <= 1:
            path = ast.literal_eval(node.args[0]) if node.args else "app.db"
            return f"sqlite:///./{path.lstrip('./')}"
        if node.func.id.endswith("Config") or node.func.id in {"SiteConfig", "OneSiteConfig"}:
            if node.args or any(k.arg is None for k in node.keywords):
                raise ValueError("展开参数需使用源码编辑")
            return {k.arg: static_value(k.value) for k in node.keywords}
    if isinstance(node, ast.Dict):
        return {ast.literal_eval(k): static_value(v) for k, v in zip(node.keys, node.values)}
    if isinstance(node, (ast.List, ast.Tuple)):
        return [static_value(v) for v in node.elts]
    return ast.literal_eval(node)


def parse_config(source):
    tree = check_python(source, "site_config.py")
    for node in tree.body:
        if isinstance(node, ast.Assign) and len(node.targets) == 1:
            if isinstance(node.targets[0], ast.Name) and node.targets[0].id == "config":
                # Preserve expressions such as env(...) per top-level key.
                if isinstance(node.value, ast.Call) and isinstance(node.value.func, ast.Name):
                    if node.value.func.id != "SiteConfig" or node.value.args:
                        break
                    values, expressions = {}, {}
                    for kw in node.value.keywords:
                        if kw.arg is None:
                            raise EditorError("config 含 ** 展开，请使用源码编辑。")
                        try:
                            values[kw.arg] = static_value(kw.value)
                        except (ValueError, TypeError):
                            expressions[kw.arg] = ast.get_source_segment(source, kw.value)
                    return {
                        "values": values,
                        "expressions": expressions,
                        "prefix": "\n".join(source.splitlines()[: node.lineno - 1]),
                        "suffix": "\n".join(source.splitlines()[node.end_lineno :]),
                    }
    raise EditorError("配置采用动态 Python 写法，请使用源码编辑；文件会完整保留。")


def render_config(spec):
    values = spec.get("values", {})
    expressions = spec.get("expressions", {})
    if not isinstance(values, dict) or not isinstance(expressions, dict):
        raise EditorError("配置值和表达式必须是对象")
    pairs = [
        f"    {identifier(k)}={python_literal(v)},"
        for k, v in values.items()
        if k not in expressions
    ]
    pairs += [f"    {identifier(k)}={expression(v)}," for k, v in expressions.items()]
    source = (
        spec.get("prefix", "from onesite.config import SiteConfig, env, sqlite_url")
        + "\n\nconfig = SiteConfig(\n"
        + "\n".join(pairs)
        + "\n)\n"
        + spec.get("suffix", "")
    )
    check_python(source, "site_config.py")
    return source


def parse_model(source):
    tree = check_python(source, "model.py")
    # Keep inheritance, helper enums, decorators and unusual class definitions in
    # the source editor rather than attempting a lossy round trip.
    classes = [n for n in tree.body if isinstance(n, ast.ClassDef)]
    if len(classes) != 1:
        raise EditorError("此文件包含多个类或继承结构，请使用源码编辑，原有内容不会被转换。")
    cls = classes[0]
    if (
        cls.decorator_list
        or len(cls.bases) != 1
        or not isinstance(cls.bases[0], ast.Name)
        or cls.bases[0].id != "SQLModel"
        or any(k.arg != "table" for k in cls.keywords)
    ):
        raise EditorError("此模型使用自定义继承或装饰器，请使用源码编辑。")
    result = {
        "name": cls.name,
        "table": any(ast.literal_eval(k.value) for k in cls.keywords),
        "table_name": "",
        "config": {},
        "fields": [],
        "hooks": "",
        "extra": "",
        "docstring": "",
        "prefix": "\n".join(source.splitlines()[: cls.lineno - 1]),
        "suffix": "\n".join(source.splitlines()[cls.end_lineno :]),
    }
    extra, methods = [], []
    for node in cls.body:
        if (
            node is cls.body[0]
            and isinstance(node, ast.Expr)
            and isinstance(node.value, ast.Constant)
        ):
            if isinstance(node.value.value, str):
                result["docstring"] = repr(node.value.value)
                continue
        if (
            isinstance(node, ast.Assign)
            and len(node.targets) == 1
            and isinstance(node.targets[0], ast.Name)
        ):
            name = node.targets[0].id
            if name == "__onesite__":
                try:
                    result["config"] = static_value(node.value)
                    if not isinstance(result["config"], dict):
                        raise ValueError("__onesite__ 必须是字典")
                except (ValueError, TypeError) as exc:
                    raise EditorError("__onesite__ 包含动态表达式，请使用源码编辑。") from exc
                continue
            if name == "__tablename__":
                result["table_name"] = ast.literal_eval(node.value)
                continue
        if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            if node.target.id.startswith("__") or methods:
                raise EditorError("此类的字段声明依赖特殊定义顺序，请使用源码编辑。")
            field = {
                "name": node.target.id,
                "type": ast.get_source_segment(source, node.annotation),
                "kwargs": {},
                "props": {},
                "value": None,
            }
            call = node.value
            if (
                isinstance(call, ast.Call)
                and isinstance(call.func, ast.Name)
                and call.func.id == "Field"
            ):
                if call.args or any(k.arg is None for k in call.keywords):
                    raise EditorError("Field 含位置参数或展开参数，请使用源码编辑。")
                for kw in call.keywords:
                    field["kwargs"][kw.arg] = ast.get_source_segment(source, kw.value)
                if "sa_column_kwargs" in field["kwargs"]:
                    try:
                        column = ast.literal_eval(field["kwargs"]["sa_column_kwargs"])
                        info = column.get("info", {})
                        if isinstance(info.get("site_props"), dict):
                            field["props"] = info.pop("site_props")
                            if not info:
                                column.pop("info", None)
                            if column:
                                field["kwargs"]["sa_column_kwargs"] = python_literal(column)
                            else:
                                del field["kwargs"]["sa_column_kwargs"]
                    except (ValueError, TypeError, AttributeError):
                        pass
                elif "sa_column" in field["kwargs"]:
                    try:
                        column = ast.parse(field["kwargs"]["sa_column"], mode="eval").body
                        if (
                            isinstance(column, ast.Call)
                            and (
                                (isinstance(column.func, ast.Name) and column.func.id == "Column")
                                or (
                                    isinstance(column.func, ast.Attribute)
                                    and column.func.attr == "Column"
                                )
                            )
                            and not any(k.arg is None for k in column.keywords)
                        ):
                            info_kw = next((k for k in column.keywords if k.arg == "info"), None)
                            info = ast.literal_eval(info_kw.value) if info_kw else {}
                            if isinstance(info.get("site_props"), dict):
                                field["props"] = info.pop("site_props")
                                if info:
                                    info_kw.value = ast.parse(
                                        python_literal(info), mode="eval"
                                    ).body
                                else:
                                    column.keywords.remove(info_kw)
                                field["kwargs"]["sa_column"] = ast.unparse(column)
                    except (ValueError, TypeError, AttributeError, SyntaxError):
                        pass
            elif call is not None:
                field["value"] = ast.get_source_segment(source, call)
            else:
                field["value"] = ""
            result["fields"].append(field)
            continue
        start = min([node.lineno] + [d.lineno for d in getattr(node, "decorator_list", [])])
        block = textwrap.dedent("\n".join(source.splitlines()[start - 1 : node.end_lineno]))
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            methods.append(block)
        elif not isinstance(node, ast.Pass):
            if not (
                isinstance(node, ast.Assign)
                and len(node.targets) == 1
                and isinstance(node.targets[0], ast.Name)
                and node.targets[0].id in {"__table_args__", "__mapper_args__"}
            ):
                raise EditorError("此类包含自定义类语句，请使用源码编辑以保留执行顺序。")
            extra.append(block)
    result["hooks"] = "\n\n".join(methods)
    result["extra"] = "\n\n".join(extra)
    return result


def render_model(spec):
    name = identifier(spec.get("name"))
    config = spec.get("config", {})
    if not isinstance(config, dict):
        raise EditorError("__onesite__ 必须为 JSON 对象")
    lines = []
    if spec.get("docstring"):
        lines.append(spec["docstring"])
    if spec.get("table_name"):
        lines.append("__tablename__ = " + repr(spec["table_name"]))
    lines.append("__onesite__ = " + python_literal(config))
    names = set()
    for field in spec.get("fields", []):
        fname = identifier(field.get("name"))
        if fname in names or fname.startswith("__"):
            raise EditorError(f"字段名重复或为保留名称：{fname}")
        names.add(fname)
        annotation = expression(field.get("type"))
        kwargs = copy.deepcopy(field.get("kwargs", {}))
        if not isinstance(kwargs, dict) or not isinstance(field.get("props", {}), dict):
            raise EditorError(f"{fname}: Field 参数和 site_props 必须为对象")
        if field.get("props"):
            try:
                if "sa_column" in kwargs:
                    column = ast.parse(kwargs["sa_column"], mode="eval").body
                    if (
                        not isinstance(column, ast.Call)
                        or not (
                            (isinstance(column.func, ast.Name) and column.func.id == "Column")
                            or (
                                isinstance(column.func, ast.Attribute)
                                and column.func.attr == "Column"
                            )
                        )
                        or any(k.arg is None for k in column.keywords)
                    ):
                        raise ValueError("dynamic Column expression")
                    info_kw = next((k for k in column.keywords if k.arg == "info"), None)
                    info = ast.literal_eval(info_kw.value) if info_kw else {}
                    info["site_props"] = {**info.get("site_props", {}), **field["props"]}
                    value = ast.parse(python_literal(info), mode="eval").body
                    if info_kw:
                        info_kw.value = value
                    else:
                        column.keywords.append(ast.keyword(arg="info", value=value))
                    kwargs["sa_column"] = ast.unparse(column)
                else:
                    column_kwargs = ast.literal_eval(kwargs.get("sa_column_kwargs", "{}"))
                    info = column_kwargs.setdefault("info", {})
                    info["site_props"] = {**info.get("site_props", {}), **field["props"]}
                    kwargs["sa_column_kwargs"] = python_literal(column_kwargs)
            except (ValueError, TypeError, AttributeError, SyntaxError) as exc:
                raise EditorError(
                    f"{fname}: SQLAlchemy 元数据包含动态表达式，请在源码中的 info 内配置 site_props。"
                ) from exc
        value = field.get("value")
        if value is not None:
            if kwargs or field.get("props"):
                raise EditorError(f"{fname}: 清除自定义赋值后才能配置 Field 参数。")
            suffix = " = " + expression(value) if value else ""
        else:
            pairs = [f"{identifier(k)}={expression(v)}" for k, v in kwargs.items()]
            suffix = " = Field(" + ", ".join(pairs) + ")"
        lines.append(f"{fname}: {annotation}{suffix}")
    if spec.get("extra", "").strip():
        lines.append(textwrap.dedent(spec["extra"]).strip())
    if spec.get("hooks", "").strip():
        lines.append(textwrap.dedent(spec["hooks"]).strip())
    source = (
        spec.get("prefix", MODEL_IMPORTS).rstrip()
        + "\n\n\nclass "
        + name
        + ("(SQLModel, table=True):\n" if spec.get("table", True) else "(SQLModel):\n")
        + textwrap.indent("\n\n".join(lines), "    ")
        + "\n"
        + spec.get("suffix", "")
    )
    check_python(source, f"{name}.py")
    return source


def is_editable(relative):
    p = PurePosixPath(relative)
    if (
        not relative
        or "\\" in relative
        or p.is_absolute()
        or ".." in p.parts
        or str(p) != relative
        or any(part in SKIP_DIRS for part in p.parts)
    ):
        return False
    if relative in {
        "site_config.py",
        "site_config.json",
        "visualizations.py",
        "deploy/.env",
        "deploy/.env.example",
    }:
        return True
    return (
        len(p.parts) > 1
        and p.parts[0] == "app"
        and (p.suffix in TEXT_EXTENSIONS or p.name in {"Dockerfile", "Makefile", "Cargo.lock"})
    )


def safe_file(project, relative):
    if not isinstance(relative, str) or not is_editable(relative):
        raise EditorError(f"不可编辑的路径：{relative!r}")
    target = project / relative
    for p in (target, *target.parents):
        if p == project:
            break
        if p.is_symlink():
            raise EditorError(f"不允许通过符号链接编辑：{relative}")
    if not target.resolve().is_relative_to(project.resolve()):
        raise EditorError("路径超出项目目录")
    return target


def digest(files):
    return hashlib.sha256(
        json.dumps(files, sort_keys=True, ensure_ascii=False).encode()
    ).hexdigest()


class Job:
    def __init__(self, project, action, argv, cwd, env):
        self.id = secrets.token_hex(8)
        self.project, self.action, self.argv = project, action, argv
        self.lines = deque(maxlen=3000)
        self.sequence = 0
        self.lock = threading.Lock()
        self.started = time.time()
        self.finished = None
        self.code = None
        self.stopping = False
        self.process = subprocess.Popen(
            argv,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            stdin=subprocess.DEVNULL,
            start_new_session=os.name != "nt",
            creationflags=subprocess.CREATE_NEW_PROCESS_GROUP if os.name == "nt" else 0,
        )
        threading.Thread(target=self._read, daemon=True).start()

    def _read(self):
        import codecs

        decoder = codecs.getincrementaldecoder("utf-8")("replace")
        try:
            while chunk := self.process.stdout.read1(4096):
                value = decoder.decode(chunk)
                with self.lock:
                    self.sequence += 1
                    self.lines.append({"seq": self.sequence, "text": value})
        finally:
            self.process.stdout.close()
            self.code = self.process.wait()
            self.finished = time.time()

    def snapshot(self, after=0):
        with self.lock:
            return {
                "id": self.id,
                "project": self.project,
                "action": self.action,
                "argv": self.argv,
                "started": self.started,
                "finished": self.finished,
                "code": self.code,
                "running": self.finished is None,
                "stopping": self.stopping,
                "cursor": self.sequence,
                "truncated": bool(self.lines and after < self.lines[0]["seq"] - 1),
                "logs": [line for line in self.lines if line["seq"] > after],
            }

    def stop(self):
        if self.finished is not None:
            return
        self.stopping = True
        try:
            if os.name == "nt":
                subprocess.run(
                    ["taskkill", "/PID", str(self.process.pid), "/T", "/F"],
                    capture_output=True,
                    timeout=10,
                )
            else:
                # Always signal the process group, including when its leader has
                # exited but a reload worker still holds the stdout pipe open.
                os.killpg(self.process.pid, signal.SIGTERM)
                deadline = time.monotonic() + 3
                while time.monotonic() < deadline:
                    try:
                        os.killpg(self.process.pid, 0)
                    except ProcessLookupError:
                        return
                    time.sleep(0.05)
                os.killpg(self.process.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass


class Studio:
    def __init__(self, root: Path, python=sys.executable):
        self.root = root.expanduser().resolve()
        self.root.mkdir(parents=True, exist_ok=True)
        # Resolving a venv Python symlink would silently switch to its base
        # interpreter and lose the user's installed OneSite/dependencies.
        self.python = os.path.abspath(os.path.expanduser(python))
        self.token = secrets.token_urlsafe(32)
        self.lock = threading.RLock()
        self.jobs = {}
        self.env = dict(os.environ, PYTHONUNBUFFERED="1", NO_COLOR="1", TERM="dumb")
        self.env["PATH"] = str(Path(self.python).parent) + os.pathsep + self.env.get("PATH", "")
        self.cli = [self.python, "-m", "onesite.main"]
        self.catalog = self._catalog()

    def _catalog(self):
        script = (
            "import json; from onesite.config import SiteConfig, OneSiteConfig; "
            "print(json.dumps({'site': SiteConfig.model_json_schema(), "
            "'model': OneSiteConfig.model_json_schema()}))"
        )
        try:
            result = subprocess.run(
                [self.python, "-c", script],
                env=self.env,
                cwd=Path(__file__).resolve().parent,
                capture_output=True,
                text=True,
                timeout=20,
            )
            if result.returncode:
                raise RuntimeError(result.stderr.strip())
            return {**json.loads(result.stdout), "available": True, "hooks": HOOKS}
        except (OSError, RuntimeError, ValueError, subprocess.TimeoutExpired) as exc:
            return {
                "available": False,
                "error": str(exc),
                "hooks": HOOKS,
                "site": {"properties": {}},
                "model": {"properties": {}},
            }

    def project(self, name, must_exist=True):
        if not isinstance(name, str) or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_-]{0,63}", name):
            raise EditorError("项目名需以英文字母开头，只含字母、数字、_ 或 -，最长 64 字符。")
        path = self.root / name
        if path.is_symlink() or path.resolve().parent != self.root:
            raise EditorError("项目不可为符号链接")
        if must_exist and not path.is_dir():
            raise EditorError("项目不存在", 404)
        return path

    def listing(self):
        result = []
        for path in sorted(self.root.iterdir()):
            if (
                path.is_dir()
                and not path.is_symlink()
                and re.fullmatch(r"[A-Za-z][A-Za-z0-9_-]{0,63}", path.name)
            ):
                if any((path / name).is_file() for name in ("site_config.py", "site_config.json")):
                    result.append({"name": path.name, "path": str(path)})
        return result

    def read(self, name):
        project = self.project(name)
        files, skipped = {}, []
        for base, dirs, names in os.walk(project, followlinks=False):
            # Source only: never scan generated output or node_modules.
            dirs[:] = [
                d
                for d in dirs
                if d not in SKIP_DIRS
                and not (Path(base) / d).is_symlink()
                and (Path(base) != project or d in {"app", "deploy"})
            ]
            for item in sorted(names):
                path = Path(base) / item
                rel = path.relative_to(project).as_posix()
                if not is_editable(rel):
                    continue
                if path.is_symlink() or path.stat().st_size > MAX_FILE:
                    skipped.append(rel)
                    continue
                try:
                    files[rel] = path.read_text(encoding="utf-8")
                except UnicodeDecodeError:
                    skipped.append(rel)
        return {
            "name": name,
            "path": str(project),
            "files": files,
            "revision": digest(files),
            "skipped": skipped,
        }

    def active(self, name):
        return [j for j in self.jobs.values() if j.project == name and j.finished is None]

    def create(self, name):
        with self.lock:
            target = self.project(name, False)
            if target.exists():
                raise EditorError("项目已存在，请打开现有项目。", 409)
            # A failed CLI create must not leave a half-created project visible.
            with tempfile.TemporaryDirectory(prefix=".webui-create-", dir=self.root) as tmp:
                result = subprocess.run(
                    self.cli + ["create", name],
                    cwd=tmp,
                    env=self.env,
                    capture_output=True,
                    text=True,
                    timeout=90,
                )
                if result.returncode or not (Path(tmp) / name / "site_config.py").exists():
                    raise EditorError("site create 失败：\n" + result.stdout + result.stderr)
                os.rename(Path(tmp) / name, target)
            return self.read(name)

    def save(self, name, files, revision, baseline=None):
        with self.lock:
            if self.active(name):
                raise EditorError("请先停止当前项目的命令，再保存或修改源文件。", 409)
            current = self.read(name)
            if revision != current["revision"]:
                if not isinstance(baseline, dict) or digest(baseline) != revision:
                    raise EditorError(
                        "磁盘内容已被其他窗口或编辑器修改。请先导出草稿，再重新打开项目合并修改。",
                        409,
                    )
                if not isinstance(files, dict):
                    raise EditorError("文件集合无效")
                # site sync itself can scaffold app files. Merge independent
                # edits against the editor's baseline, never overwrite an
                # externally edited file when both sides changed it.
                missing = object()
                local_changes = {
                    key
                    for key in set(baseline) | set(files)
                    if baseline.get(key, missing) != files.get(key, missing)
                }
                conflicts = [
                    key
                    for key in local_changes
                    if current["files"].get(key, missing) != baseline.get(key, missing)
                    and current["files"].get(key, missing) != files.get(key, missing)
                ]
                if conflicts:
                    raise EditorError(
                        "以下文件同时在网页和磁盘中被修改，请导出草稿后合并：\n"
                        + "\n".join(sorted(conflicts)),
                        409,
                    )
                merged = dict(current["files"])
                for key in local_changes:
                    if key in files:
                        merged[key] = files[key]
                    else:
                        merged.pop(key, None)
                files = merged
            if not isinstance(files, dict) or len(files) > 1500:
                raise EditorError("文件集合无效或超过 1500 个文件")
            if not any(k in files for k in ("site_config.py", "site_config.json")):
                raise EditorError("项目必须保留 site_config.py 或 site_config.json")
            project = self.project(name)
            for rel, content in files.items():
                target = safe_file(project, rel)
                if target.exists() and rel not in current["files"]:
                    raise EditorError(f"{rel} 未被编辑器加载，不能覆盖。")
                if not isinstance(content, str) or len(content.encode()) > MAX_FILE:
                    raise EditorError(f"文件过大或内容无效：{rel}")
                if rel.endswith(".py"):
                    check_python(content, rel)
                elif rel.endswith(".json"):
                    try:
                        json.loads(content)
                    except ValueError as exc:
                        raise EditorError(f"{rel}: {exc}") from exc
            changed = {k: v for k, v in files.items() if current["files"].get(k) != v}
            deleted = set(current["files"]) - set(files)
            # Stage and validate the entire change set before touching files. Keep
            # the original bytes for rollback if any filesystem operation fails.
            with tempfile.TemporaryDirectory(prefix=".webui-save-", dir=project) as tmp:
                stage = Path(tmp)
                for rel, content in changed.items():
                    path = stage / rel
                    path.parent.mkdir(parents=True, exist_ok=True)
                    path.write_text(content, encoding="utf-8")
                    old = safe_file(project, rel)
                    if old.exists():
                        shutil.copymode(old, path)
                touched = []
                try:
                    for rel in changed:
                        target = safe_file(project, rel)
                        target.parent.mkdir(parents=True, exist_ok=True)
                        os.replace(stage / rel, target)
                        touched.append(rel)
                    for rel in deleted:
                        safe_file(project, rel).unlink()
                        touched.append(rel)
                except OSError:
                    for rel in reversed(touched):
                        target = safe_file(project, rel)
                        if rel in current["files"]:
                            target.write_text(current["files"][rel], encoding="utf-8")
                        else:
                            target.unlink(missing_ok=True)
                    raise
            return self.read(name)

    def start(self, name, action, options, revision):
        with self.lock:
            project = self.project(name)
            if self.active(name):
                raise EditorError("该项目已有命令正在执行，请先停止或等待完成。", 409)
            if self.read(name)["revision"] != revision:
                raise EditorError("项目内容已变化，请重新打开后再执行。", 409)
            if action == "sync":
                argv = self.cli + ["sync"]
                if options.get("install"):
                    argv.append("--install")
                if options.get("build_cmd"):
                    argv.append("--build-cmd")
            elif action == "run":
                component = options.get("component", "all")
                if component not in {"all", "frontend", "backend"}:
                    raise EditorError("无效的运行组件")
                required = []
                if component in {"all", "backend"}:
                    required.append(project / "generated/backend/app/api/api.py")
                if component in {"all", "frontend"}:
                    required.append(project / "generated/frontend/src/Routes.tsx")
                if any(not path.exists() for path in required):
                    raise EditorError("请先执行 Sync 生成项目代码。")
                # The current CLI uses --component, not a positional component.
                argv = self.cli + ["run", ".", "--component", component, "--host", "127.0.0.1"]
            else:
                raise EditorError("仅支持 sync 和 run")
            # Bound retained job history without discarding active commands.
            for job_id in list(self.jobs):
                if len(self.jobs) < 60:
                    break
                if self.jobs[job_id].finished is not None:
                    del self.jobs[job_id]
            job = Job(name, action, argv, project, self.env)
            self.jobs[job.id] = job
            return job.snapshot()

    def close(self):
        for job in list(self.jobs.values()):
            if job.finished is None:
                job.stop()


class Handler(BaseHTTPRequestHandler):
    server_version = "OneSiteStudio/1"

    def log_message(self, fmt, *args):
        # Do not log project contents, tokens or query parameters.
        pass

    @property
    def studio(self):
        return self.server.studio

    def send(self, status, body, html=False, asset_type=None):
        payload = (
            body
            if asset_type
            else (body.encode() if html else json.dumps(body, ensure_ascii=False).encode())
        )
        self.send_response(status)
        self.send_header(
            "Content-Type",
            asset_type
            or ("text/html; charset=utf-8" if html else "application/json; charset=utf-8"),
        )
        if asset_type:
            self.send_header("Content-Encoding", "gzip")
        self.send_header("Content-Length", str(len(payload)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header(
            "Content-Security-Policy",
            "default-src 'none'; script-src 'nonce-"
            + self.studio.token
            + "'; style-src 'self' 'unsafe-inline'; connect-src 'self'; "
            "img-src 'self' data:; frame-ancestors 'none'; base-uri 'none'; form-action 'none'",
        )
        self.end_headers()
        self.wfile.write(payload)

    def guard(self, api=False):
        port = self.server.server_address[1]
        allowed = {f"127.0.0.1:{port}", f"localhost:{port}"}
        if self.headers.get("Host") not in allowed:
            raise EditorError("Invalid host", 403)
        origin = self.headers.get("Origin")
        if origin and origin not in {f"http://{host}" for host in allowed}:
            raise EditorError("Cross-origin requests are not allowed", 403)
        if self.headers.get("Sec-Fetch-Site") == "cross-site":
            raise EditorError("Cross-site requests are not allowed", 403)
        if api and not secrets.compare_digest(
            self.headers.get("X-Studio-Token", ""), self.studio.token
        ):
            raise EditorError("Invalid studio token; reload the page", 403)

    def do_GET(self):
        try:
            self.guard()
            path = urlsplit(self.path).path
            if path in ASSETS:
                mime, payload = ASSETS[path]
                self.send(200, payload, asset_type=mime)
                return
            if path not in {"/", "/favicon.ico"}:
                raise EditorError("Not found", 404)
            if path == "/favicon.ico":
                self.send(200, {})
            else:
                self.send(200, HTML.replace("__STUDIO_TOKEN__", self.studio.token), html=True)
        except EditorError as exc:
            self.send(exc.status, {"error": str(exc)})

    def do_POST(self):
        try:
            self.guard(api=True)
            if self.headers.get("Content-Type", "").split(";")[0] != "application/json":
                raise EditorError("Expected application/json", 415)
            length = int(self.headers.get("Content-Length", "0"))
            if not 0 < length <= MAX_BODY:
                raise EditorError("请求大小超过限制", 413)
            data = json.loads(self.rfile.read(length))
            if not isinstance(data, dict):
                raise EditorError("Expected an object")
            self.send(200, self.dispatch(urlsplit(self.path).path, data))
        except EditorError as exc:
            self.send(exc.status, {"error": str(exc)})
        except (ValueError, TypeError, KeyError, AttributeError) as exc:
            self.send(400, {"error": f"请求无效：{exc}"})
        except subprocess.TimeoutExpired:
            self.send(504, {"error": "命令执行超时，请检查 OneSite 环境。"})
        except OSError as exc:
            self.send(500, {"error": f"文件或进程操作失败：{exc}"})

    def dispatch(self, path, data):
        studio = self.studio
        if path == "/api/bootstrap":
            return {
                "projects": studio.listing(),
                "root": str(studio.root),
                "catalog": studio.catalog,
                "python": studio.python,
                "model_imports": MODEL_IMPORTS,
            }
        if path == "/api/create":
            return studio.create(data["name"])
        if path == "/api/open":
            with studio.lock:
                return studio.read(data["name"])
        if path == "/api/save":
            return studio.save(data["name"], data["files"], data["revision"], data.get("baseline"))
        if path == "/api/parse":
            return (parse_config if data["kind"] == "config" else parse_model)(data["source"])
        if path == "/api/render":
            return {
                "source": (render_config if data["kind"] == "config" else render_model)(
                    data["spec"]
                )
            }
        if path == "/api/validate":
            for name, source in data["files"].items():
                if not is_editable(name):
                    raise EditorError(f"不可编辑的路径：{name}")
                if not isinstance(source, str) or len(source.encode()) > MAX_FILE:
                    raise EditorError(f"文件过大或内容无效：{name}")
                if name.endswith(".py"):
                    check_python(source, name)
                if name.endswith(".json"):
                    json.loads(source)
            return {"valid": True}
        if path == "/api/start":
            return studio.start(
                data["name"], data["action"], data.get("options", {}), data["revision"]
            )
        if path == "/api/jobs":
            with studio.lock:
                return {
                    "jobs": [
                        j.snapshot(int(data.get("cursors", {}).get(j.id, 0)))
                        for j in studio.jobs.values()
                        if j.project == data["name"]
                    ]
                }
        if path == "/api/stop":
            job = studio.jobs.get(data["id"])
            if job is None:
                raise EditorError("命令不存在", 404)
            job.stop()
            return job.snapshot()
        raise EditorError("Not found", 404)


